cat > parse_csv.py <<'EOF'
"""Parse a large CSV file and compute column sums.

Performance notes (stdlib only):
  * Rows are read in small chunks and transposed with ``zip(*chunk)`` so the
    per-cell work (``float`` + summation) runs in C via ``map``/``sum``
    instead of a Python-level nested loop.
  * Large files without quote characters are split into newline-aligned byte
    ranges and summed in parallel worker processes. Files containing ``"``
    (which may have quoted newlines) always use the single-process path, so
    parsing is never split in the middle of a record.
  * Semantics match the original: non-numeric cells are skipped, short rows
    are fine, rows longer than the header raise IndexError.
"""
import csv
import io
import mmap
import os
from concurrent.futures import ProcessPoolExecutor
from itertools import islice

CHUNK_ROWS = 1024
PARALLEL_MIN_BYTES = 32 * 1024 * 1024  # below this, process startup isn't worth it


def _sum_cells(cells):
    """Sum the cells that parse as float, skipping the rest."""
    try:
        return sum(map(float, cells))
    except ValueError:
        total = 0.0
        for v in cells:
            try:
                total += float(v)
            except ValueError:
                pass
        return total


def _sum_rows(reader, n):
    """Accumulate column totals for all rows of ``reader`` (header consumed)."""
    totals = [0.0] * n
    while True:
        chunk = list(islice(reader, CHUNK_ROWS))
        if not chunk:
            return totals
        if all(len(row) == n for row in chunk):
            for i, col in enumerate(zip(*chunk)):
                totals[i] += _sum_cells(col)
        else:
            # Ragged chunk: original row-by-row logic (keeps IndexError on
            # over-long rows and tolerates short/blank rows).
            for row in chunk:
                for i, v in enumerate(row):
                    try:
                        totals[i] += float(v)
                    except ValueError:
                        pass


def _sum_range(path, start, end, n):
    with open(path, "rb") as f:
        f.seek(start)
        data = f.read(end - start)
    # encoding=None -> same locale default that open() uses in the serial path.
    text = io.TextIOWrapper(io.BytesIO(data), encoding=None, newline="")
    return _sum_rows(csv.reader(text), n)


def _split_points(mm, start, size, parts):
    """Newline-aligned byte offsets dividing [start, size) into ~parts ranges."""
    points = [start]
    step = (size - start) // parts
    for k in range(1, parts):
        nl = mm.find(b"\n", max(start + k * step, points[-1]))
        if nl == -1:
            break
        points.append(nl + 1)
    points.append(size)
    return sorted(set(points))


def sum_columns(path, workers=None):
    with open(path, newline="") as f:
        reader = csv.reader(f)
        header = next(reader)
        n = len(header)
        size = os.path.getsize(path)
        workers = workers or os.cpu_count() or 1
        if workers == 1 or size < PARALLEL_MIN_BYTES:
            return dict(zip(header, _sum_rows(reader, n)))

    with open(path, "rb") as fb, mmap.mmap(fb.fileno(), 0, access=mmap.ACCESS_READ) as mm:
        if mm.find(b'"') != -1:
            # Quoted fields may contain newlines: can't split safely.
            with open(path, newline="") as f:
                reader = csv.reader(f)
                next(reader)
                return dict(zip(header, _sum_rows(reader, n)))
        body_start = mm.find(b"\n") + 1
        points = _split_points(mm, body_start, size, workers)

    totals = [0.0] * n
    with ProcessPoolExecutor(max_workers=len(points) - 1) as ex:
        futures = [ex.submit(_sum_range, path, a, b, n)
                   for a, b in zip(points, points[1:])]
        for fut in futures:  # in order, so errors surface deterministically
            for i, v in enumerate(fut.result()):
                totals[i] += v
    return dict(zip(header, totals))


if __name__ == "__main__":
    import sys
    print(sum_columns(sys.argv[1]))
